package com.example.starter.payment;

import java.time.Instant;
import java.time.LocalDate;
import java.time.LocalTime;
import java.time.ZoneOffset;

/**
 * 日切工具：交易按 UTC 每日 16:00 日切。
 * 交易时刻早于 16:00 归入当日批次；达到或晚于 16:00（含 16:00:00 整点）归入次日批次。
 */
public final class CutoffClock {

    /** 日切时刻（UTC）。 */
    public static final LocalTime CUTOFF_TIME = LocalTime.of(16, 0);

    private CutoffClock() {
    }

    /**
     * 计算交易时间归属的批次日期（UTC）。
     *
     * @param txnTime 交易时间（UTC 瞬间）
     * @return 批次日期
     */
    public static LocalDate batchDateOf(Instant txnTime) {
        var utc = txnTime.atZone(ZoneOffset.UTC);
        LocalDate date = utc.toLocalDate();
        return utc.toLocalTime().isBefore(CUTOFF_TIME) ? date : date.plusDays(1);
    }
}

package com.example.starter.payment;

/**
 * 商户（合成数据）。
 *
 * @param merchantNo   商户号
 * @param merchantName 商户名称
 * @param feeRateBp    手续费率，单位基点（1bp = 0.01%）
 */
public record Merchant(String merchantNo, String merchantName, int feeRateBp) {
}

package com.example.starter.payment;

import java.time.Instant;
import java.time.LocalDate;

/**
 * 日切批次。
 *
 * @param id        批次ID
 * @param batchDate 批次日期（UTC 日切归属日）
 * @param status    状态：OPEN 开放 / CLOSED 已封账（终态）
 * @param closedAt  封账时间（UTC），未封账为 null
 */
public record PayBatch(long id, LocalDate batchDate, String status, Instant closedAt) {

    public static final String OPEN = "OPEN";
    public static final String CLOSED = "CLOSED";

    public boolean isClosed() {
        return CLOSED.equals(status);
    }
}

package com.example.starter.payment;

import java.time.Instant;

/**
 * 支付交易。
 *
 * @param id          交易ID
 * @param requestId   入账请求幂等键
 * @param fingerprint 幂等指纹（requestId+流水号+金额+商户号 哈希）
 * @param serialNo    渠道流水号，全局唯一
 * @param merchantNo  商户号
 * @param amount      交易金额，单位分
 * @param fee         手续费，单位分
 * @param txnTime     交易时间（UTC）
 * @param batchId     归属批次ID；挂账时为 null
 * @param status      状态：POSTED 已入账 / SUSPENDED 挂账
 */
public record PayTransaction(long id, String requestId, String fingerprint, String serialNo,
                             String merchantNo, long amount, long fee, Instant txnTime,
                             Long batchId, String status) {

    public static final String POSTED = "POSTED";
    public static final String SUSPENDED = "SUSPENDED";
}

package com.example.starter.payment;

/**
 * 清算单（每批次每商户一单）。
 *
 * @param id          清算单ID
 * @param batchId     批次ID
 * @param merchantNo  商户号
 * @param txnCount    交易笔数
 * @param totalAmount 交易总额，单位分
 * @param totalFee    手续费总额，单位分
 * @param netAmount   清算净额（交易额-手续费），单位分
 */
public record SettlementBill(long id, long batchId, String merchantNo, int txnCount,
                             long totalAmount, long totalFee, long netAmount) {
}

package com.example.starter.payment;

import java.time.Instant;

/**
 * 对账差异记录。
 *
 * @param id           差异ID
 * @param batchId      对账批次ID
 * @param serialNo     渠道流水号
 * @param diffType     差异类型：LOCAL_EXCESS 本地多账 / CHANNEL_EXCESS 渠道多账 / AMOUNT_MISMATCH 金额差错
 * @param localAmount  本地金额（分），渠道多账时为 null
 * @param channelAmount 渠道金额（分），本地多账时为 null
 * @param status       状态：OPEN 待处理 / RESOLVED 已处理
 * @param resolution   处理方式：WRITE_OFF 核销 / REPOST 补记 / REFUND 退款；未处理为 null
 * @param resolvedBy   处理人；未处理为 null
 * @param resolvedAt   处理时间（UTC）；未处理为 null
 */
public record ReconDifference(long id, long batchId, String serialNo, String diffType,
                              Long localAmount, Long channelAmount, String status,
                              String resolution, String resolvedBy, Instant resolvedAt) {

    public static final String LOCAL_EXCESS = "LOCAL_EXCESS";
    public static final String CHANNEL_EXCESS = "CHANNEL_EXCESS";
    public static final String AMOUNT_MISMATCH = "AMOUNT_MISMATCH";

    public static final String OPEN = "OPEN";
    public static final String RESOLVED = "RESOLVED";

    public static final String WRITE_OFF = "WRITE_OFF";
    public static final String REPOST = "REPOST";
    public static final String REFUND = "REFUND";
}

package com.example.starter.payment;

/**
 * 业务异常，携带 HTTP 状态语义，由全局异常处理器映射为响应。
 */
public class BizException extends RuntimeException {

    private final int httpStatus;

    public BizException(int httpStatus, String message) {
        super(message);
        this.httpStatus = httpStatus;
    }

    public int httpStatus() {
        return httpStatus;
    }

    /** 400 请求参数或业务前置条件不合法。 */
    public static BizException badRequest(String message) {
        return new BizException(400, message);
    }

    /** 404 资源不存在。 */
    public static BizException notFound(String message) {
        return new BizException(404, message);
    }

    /** 409 幂等冲突 / 状态冲突。 */
    public static BizException conflict(String message) {
        return new BizException(409, message);
    }
}

