package com.example.starter.payment.service;

import com.example.starter.payment.BizException;
import com.example.starter.payment.CutoffClock;
import com.example.starter.payment.Merchant;
import com.example.starter.payment.PayBatch;
import com.example.starter.payment.PayTransaction;
import com.example.starter.payment.repo.BatchRepository;
import com.example.starter.payment.repo.MerchantRepository;
import com.example.starter.payment.repo.TransactionRepository;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Instant;
import java.time.LocalDate;
import java.util.HexFormat;
import java.util.Optional;

/**
 * 入账服务：requestId 幂等、渠道流水号去重、按 UTC 16:00 日切归属批次；
 * 批次已封账时交易进入挂账。
 */
@Service
public class PaymentService {

    private final TransactionRepository txnRepo;
    private final BatchRepository batchRepo;
    private final MerchantRepository merchantRepo;

    public PaymentService(TransactionRepository txnRepo, BatchRepository batchRepo,
                          MerchantRepository merchantRepo) {
        this.txnRepo = txnRepo;
        this.batchRepo = batchRepo;
        this.merchantRepo = merchantRepo;
    }

    /**
     * 入账请求。
     *
     * @param requestId  幂等键
     * @param serialNo   渠道流水号
     * @param merchantNo 商户号
     * @param amount     金额（分），必须为正
     * @param txnTime    交易时间（UTC）
     */
    public record PostCommand(String requestId, String serialNo, String merchantNo,
                              long amount, Instant txnTime) {
    }

    /**
     * 入账结果。
     *
     * @param txn       交易记录
     * @param batchDate 归属批次日期；挂账时为交易按日切本应归属的批次日期
     * @param replayed  是否为幂等重放（同键同参返回首次结果）
     */
    public record PostResult(PayTransaction txn, LocalDate batchDate, boolean replayed) {
    }

    @Transactional
    public PostResult post(PostCommand cmd) {
        validate(cmd);
        String fingerprint = fingerprint(cmd);

        // 幂等：同键同参返回首次结果，同键异参 409
        Optional<PayTransaction> existing = txnRepo.findByRequestId(cmd.requestId());
        if (existing.isPresent()) {
            PayTransaction txn = existing.get();
            if (!txn.fingerprint().equals(fingerprint)) {
                throw BizException.conflict("requestId 已存在但请求参数不一致，拒绝重复入账");
            }
            return new PostResult(txn, CutoffClock.batchDateOf(txn.txnTime()), true);
        }

        Merchant merchant = merchantRepo.findByMerchantNo(cmd.merchantNo())
                .orElseThrow(() -> BizException.badRequest("商户不存在: " + cmd.merchantNo()));
        long fee = feeOf(cmd.amount(), merchant.feeRateBp());

        LocalDate batchDate = CutoffClock.batchDateOf(cmd.txnTime());
        // 锁定批次行：与封账串行化，保证交易只归属唯一批次
        PayBatch batch = batchRepo.lockOrCreate(batchDate);

        Long batchId;
        String status;
        if (batch.isClosed()) {
            // 封账后到达的该批次交易：拒绝入账，进入挂账
            batchId = null;
            status = PayTransaction.SUSPENDED;
        } else {
            batchId = batch.id();
            status = PayTransaction.POSTED;
        }

        try {
            PayTransaction txn = txnRepo.insert(cmd.requestId(), fingerprint, cmd.serialNo(),
                    cmd.merchantNo(), cmd.amount(), fee, cmd.txnTime(), batchId, status);
            return new PostResult(txn, batchDate, false);
        } catch (DuplicateKeyException e) {
            return resolveDuplicate(cmd, fingerprint);
        }
    }

    /** 并发唯一键冲突后的幂等裁决。 */
    private PostResult resolveDuplicate(PostCommand cmd, String fingerprint) {
        Optional<PayTransaction> byRequest = txnRepo.findByRequestId(cmd.requestId());
        if (byRequest.isPresent()) {
            PayTransaction txn = byRequest.get();
            if (!txn.fingerprint().equals(fingerprint)) {
                throw BizException.conflict("requestId 已存在但请求参数不一致，拒绝重复入账");
            }
            return new PostResult(txn, CutoffClock.batchDateOf(txn.txnTime()), true);
        }
        if (txnRepo.findBySerialNo(cmd.serialNo()).isPresent()) {
            throw BizException.conflict("渠道流水号已入账，不允许重复: " + cmd.serialNo());
        }
        throw BizException.conflict("入账冲突，请重试");
    }

    private void validate(PostCommand cmd) {
        if (cmd.requestId() == null || cmd.requestId().isBlank()) {
            throw BizException.badRequest("requestId 不能为空");
        }
        if (cmd.serialNo() == null || cmd.serialNo().isBlank()) {
            throw BizException.badRequest("serialNo 不能为空");
        }
        if (cmd.merchantNo() == null || cmd.merchantNo().isBlank()) {
            throw BizException.badRequest("merchantNo 不能为空");
        }
        if (cmd.amount() <= 0) {
            throw BizException.badRequest("amount 必须为正数（分）");
        }
        if (cmd.txnTime() == null) {
            throw BizException.badRequest("txnTime 不能为空");
        }
    }

    /** 手续费（分）= 金额 × 费率基点 / 10000，四舍五入到分。 */
    static long feeOf(long amount, int feeRateBp) {
        return BigDecimal.valueOf(amount).multiply(BigDecimal.valueOf(feeRateBp))
                .divide(BigDecimal.valueOf(10000), 0, RoundingMode.HALF_UP).longValueExact();
    }

    /** 幂等指纹：覆盖 requestId、流水号、金额与商户号。 */
    static String fingerprint(PostCommand cmd) {
        String material = cmd.requestId() + '|' + cmd.serialNo() + '|' + cmd.amount() + '|' + cmd.merchantNo();
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest(material.getBytes(StandardCharsets.UTF_8));
            return HexFormat.of().formatHex(digest);
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }
}

package com.example.starter.payment.service;

import com.example.starter.payment.PayBatch;
import com.example.starter.payment.SettlementBill;
import com.example.starter.payment.repo.BatchRepository;
import com.example.starter.payment.repo.SettlementBillRepository;
import com.example.starter.payment.repo.TransactionRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDate;
import java.util.List;

/**
 * 封账服务：封账为终态，重复封账返回首次清算单且不重新计算。
 */
@Service
public class SettlementService {

    private final BatchRepository batchRepo;
    private final TransactionRepository txnRepo;
    private final SettlementBillRepository billRepo;

    public SettlementService(BatchRepository batchRepo, TransactionRepository txnRepo,
                             SettlementBillRepository billRepo) {
        this.batchRepo = batchRepo;
        this.txnRepo = txnRepo;
        this.billRepo = billRepo;
    }

    /**
     * 对指定批次日期封账并生成各商户清算单。
     *
     * @param batchDate 批次日期（UTC 日切归属日）
     * @return 该批次全部清算单（重复封账时返回首次生成的清算单）
     */
    @Transactional
    public List<SettlementBill> close(LocalDate batchDate) {
        // 锁定批次行，与入账串行化
        PayBatch batch = batchRepo.lockOrCreate(batchDate);
        if (batch.isClosed()) {
            // 幂等：返回首次清算结果，不重新计算
            return billRepo.findByBatchId(batch.id());
        }
        List<SettlementBill> bills = txnRepo.aggregateByBatch(batch.id()).stream()
                .map(agg -> billRepo.insert(batch.id(), agg.merchantNo(), agg.txnCount(),
                        agg.totalAmount(), agg.totalFee()))
                .toList();
        batchRepo.markClosed(batch.id());
        return bills;
    }

    @Transactional(readOnly = true)
    public List<SettlementBill> billsOf(LocalDate batchDate) {
        return batchRepo.findByDate(batchDate)
                .map(batch -> billRepo.findByBatchId(batch.id()))
                .orElse(List.of());
    }
}

package com.example.starter.payment.service;

import com.example.starter.payment.BizException;
import com.example.starter.payment.CutoffClock;
import com.example.starter.payment.PayBatch;
import com.example.starter.payment.PayTransaction;
import com.example.starter.payment.repo.BatchRepository;
import com.example.starter.payment.repo.TransactionRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDate;

/**
 * 调账服务：将挂账交易转入下一开放批次。调账与原交易在同一事务内完成，
 * 通过行锁与单条状态更新保证不出现两边同时计额。
 */
@Service
public class AdjustmentService {

    private final TransactionRepository txnRepo;
    private final BatchRepository batchRepo;

    public AdjustmentService(TransactionRepository txnRepo, BatchRepository batchRepo) {
        this.txnRepo = txnRepo;
        this.batchRepo = batchRepo;
    }

    /**
     * 将指定流水号的挂账交易调入下一开放批次。
     *
     * @param serialNo 渠道流水号
     * @return 调账后的交易（状态 POSTED，batchId 指向开放批次）
     */
    @Transactional
    public PayTransaction adjust(String serialNo) {
        PayTransaction txn = txnRepo.lockBySerialNo(serialNo)
                .orElseThrow(() -> BizException.notFound("交易不存在: " + serialNo));
        if (!PayTransaction.SUSPENDED.equals(txn.status())) {
            throw BizException.conflict("仅挂账交易可调账，当前状态: " + txn.status());
        }
        // 从交易按日切本应归属的批次起，找到第一个开放批次
        LocalDate targetDate = CutoffClock.batchDateOf(txn.txnTime());
        PayBatch target;
        while (true) {
            target = batchRepo.lockOrCreate(targetDate);
            if (!target.isClosed()) {
                break;
            }
            targetDate = targetDate.plusDays(1);
        }
        txnRepo.moveToBatch(txn.id(), target.id());
        return new PayTransaction(txn.id(), txn.requestId(), txn.fingerprint(), txn.serialNo(),
                txn.merchantNo(), txn.amount(), txn.fee(), txn.txnTime(), target.id(),
                PayTransaction.POSTED);
    }
}

package com.example.starter.payment.service;

import com.example.starter.payment.BizException;
import com.example.starter.payment.PayBatch;
import com.example.starter.payment.PayTransaction;
import com.example.starter.payment.ReconDifference;
import com.example.starter.payment.repo.BatchRepository;
import com.example.starter.payment.repo.DifferenceRepository;
import com.example.starter.payment.repo.TransactionRepository;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * 对账服务：以渠道对账文件（合成数据）逐笔勾对，生成三类差异并支持处理留痕。
 */
@Service
public class ReconService {

    private final BatchRepository batchRepo;
    private final TransactionRepository txnRepo;
    private final DifferenceRepository diffRepo;

    public ReconService(BatchRepository batchRepo, TransactionRepository txnRepo,
                        DifferenceRepository diffRepo) {
        this.batchRepo = batchRepo;
        this.txnRepo = txnRepo;
        this.diffRepo = diffRepo;
    }

    /** 渠道对账文件条目（合成数据）。 */
    public record ChannelEntry(String serialNo, long amount) {
    }

    /**
     * 对指定批次执行对账。
     *
     * @param batchDate 批次日期
     * @param entries   渠道对账文件条目
     * @return 本次对账后该批次的全部差异记录
     */
    @Transactional
    public List<ReconDifference> reconcile(LocalDate batchDate, List<ChannelEntry> entries) {
        PayBatch batch = batchRepo.lockOrCreate(batchDate);
        List<PayTransaction> localTxns = txnRepo.findPostedByBatchId(batch.id());

        Map<String, PayTransaction> localBySerial = new HashMap<>();
        for (PayTransaction txn : localTxns) {
            localBySerial.put(txn.serialNo(), txn);
        }
        Map<String, Long> channelBySerial = new HashMap<>();
        for (ChannelEntry entry : entries) {
            if (entry.serialNo() == null || entry.serialNo().isBlank()) {
                throw BizException.badRequest("渠道对账条目 serialNo 不能为空");
            }
            channelBySerial.putIfAbsent(entry.serialNo(), entry.amount());
        }

        List<ReconDifference> created = new ArrayList<>();
        // 本地有、渠道无 → 本地多账；两边都有但金额不一致 → 差错
        for (PayTransaction txn : localTxns) {
            Long channelAmount = channelBySerial.get(txn.serialNo());
            if (channelAmount == null) {
                created.add(insertDiff(batch.id(), txn.serialNo(), ReconDifference.LOCAL_EXCESS,
                        txn.amount(), null));
            } else if (channelAmount != txn.amount()) {
                created.add(insertDiff(batch.id(), txn.serialNo(), ReconDifference.AMOUNT_MISMATCH,
                        txn.amount(), channelAmount));
            }
        }
        // 渠道有、本地无 → 渠道多账
        Set<String> localSerials = localBySerial.keySet();
        for (Map.Entry<String, Long> entry : channelBySerial.entrySet()) {
            if (!localSerials.contains(entry.getKey())) {
                created.add(insertDiff(batch.id(), entry.getKey(), ReconDifference.CHANNEL_EXCESS,
                        null, entry.getValue()));
            }
        }

        List<ReconDifference> all = new ArrayList<>(diffRepo.findByBatchId(batch.id()));
        all.addAll(created.stream()
                .filter(d -> all.stream().noneMatch(existing -> existing.id() == d.id()))
                .toList());
        return all;
    }

    /** 插入差异；同批次同流水号重复对账时忽略（唯一约束兜底）。 */
    private ReconDifference insertDiff(long batchId, String serialNo, String diffType,
                                       Long localAmount, Long channelAmount) {
        try {
            return diffRepo.insert(batchId, serialNo, diffType, localAmount, channelAmount);
        } catch (DuplicateKeyException e) {
            return diffRepo.findByBatchId(batchId).stream()
                    .filter(d -> d.serialNo().equals(serialNo))
                    .findFirst()
                    .orElseThrow(() -> e);
        }
    }

    /**
     * 处理差异（核销/补记/退款），同一差异不允许重复处理；处理结果留痕。
     *
     * @param differenceId 差异ID
     * @param resolution   WRITE_OFF 核销 / REPOST 补记 / REFUND 退款
     * @param operator     处理人
     */
    @Transactional
    public ReconDifference resolve(long differenceId, String resolution, String operator) {
        if (!Set.of(ReconDifference.WRITE_OFF, ReconDifference.REPOST, ReconDifference.REFUND)
                .contains(resolution)) {
            throw BizException.badRequest("非法处理方式: " + resolution);
        }
        if (operator == null || operator.isBlank()) {
            throw BizException.badRequest("处理人不能为空");
        }
        int updated = diffRepo.markResolved(differenceId, resolution, operator);
        if (updated == 0) {
            diffRepo.findById(differenceId)
                    .orElseThrow(() -> BizException.notFound("差异不存在: " + differenceId));
            throw BizException.conflict("差异已处理，不允许重复核销: " + differenceId);
        }
        diffRepo.insertResolutionLog(differenceId, resolution, operator);
        return diffRepo.findById(differenceId)
                .orElseThrow(() -> new IllegalStateException("差异读取失败: " + differenceId));
    }

    @Transactional(readOnly = true)
    public List<ReconDifference> differencesOf(LocalDate batchDate) {
        return batchRepo.findByDate(batchDate)
                .map(batch -> diffRepo.findByBatchId(batch.id()))
                .orElse(List.of());
    }
}

